}

.financial-progress-bar-premium {
    height: 100%;
}

.financial-progress-bar-paid {
    background-color: var(--premium-success);
}

.financial-progress-bar-cheques {
    background-color: var(--premium-warning);
    opacity: 0.75;
}

/* Legend Styles */
.financial-legend-premium {
    display: flex;
    justify-content: space-between;
    margin-top: 1rem;
    font-size: 0.7rem;
    font-weight: 700;
}

.legend-item-premium {
    display: flex;
    align-items: center;
    gap: 5px;
}

.legend-dot-premium {
    font-size: 6px;
    vertical-align: middle;
}

/* Portfolio Scrollable */
.linked-cheques-scrollable-premium {
    max-height: 250px;
    overflow-y: auto;
    overflow-x: hidden;
    padding-right: 5px;
}

/* Projected Balance Card */
.projected-balance-box-premium {
    padding: 15px;
    margin-bottom: 20px;
    text-align: center;
    background: rgba(16, 185, 129, 0.04);
    border: 1px dashed rgba(16, 185, 129, 0.3);
