}

.projected-value-premium {
    font-size: 1.25rem;
    font-weight: 900;
    color: var(--premium-success);
}

.projected-value-premium.negative {
    color: var(--premium-danger);
}

/* Cheque Details Pill */
.cheque-details-pill-premium {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 15px;
    background: #f8fafc;
    border-radius: 2px;
    border: 1px solid #e2e8f0;
