/* Smart Tag Copied Effect */
.smart-tag-copied-effect {
    transform: scale(0.95);
    background-color: #e8f5e9 !important;
    border-color: #28c76f !important;
    box-shadow: 0 0 15px rgba(40, 199, 111, 0.4) !important;
    transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1) !important;
}
.smart-tag-copied-effect .tag-code {
    background-color: #28c76f !important;
    color: #ffffff !important;
    transform: scale(1.05);
    transition: all 0.3s ease !important;
}
/* Maintenance Items Header Styles */
.maintenance-items-header {
    background: #f8fafc;
    border-bottom: 1px solid #e2e8f0;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 15px 20px;
}
.maintenance-items-header-title {
    color: #475569;
    display: flex;
    align-items: center;
    gap: 10px;
    font-weight: 700;
    font-size: 1.15rem;
}
.maintenance-items-header-title i {
    font-size: 1.3rem;
}
/* Small Premium File Box */
.premium-file-box-sm {
    min-height: 38px !important;
    height: 38px !important;
    padding: 5px 10px !important;
    border-radius: 2px !important;
}
.premium-file-box-sm .file-icon-box {
    width: 24px !important;
    height: 24px !important;
    font-size: 0.9rem !important;
}
/* Action Button Wrapper for vertical alignment */
.action-btn-wrapper {
    min-height: 42px;
}
/* File box exact match to 42px inputs */
.premium-file-box-match {
    height: 42px !important;
    min-height: 42px !important;
    padding: 0 12px !important;
}
.premium-file-box-match .file-icon-box {
    width: 24px !important;
    height: 24px !important;
    font-size: 0.9rem !important;
}
.premium-file-box-match .browse-badge {
    padding: 4px 10px !important;
}
/* Ultimate Alignment Fixes */
.premium-file-upload-wrapper {
    margin-top: 0 !important;
}
.action-btn-wrapper, .btn-premium-action {
    margin-top: 0 !important;
    margin-bottom: 0 !important;
}
.align-all-items-row .premium-input, 
.align-all-items-row .premium-file-box, 
.align-all-items-row .action-btn-wrapper, 
.align-all-items-row .btn-premium-action {
    height: 42px !important;
    min-height: 42px !important;
}
.align-all-items-row .btn-premium-action {
    width: 42px !important;
}

/* Absolute Alignment Fixes */
.maintenance-item-row .premium-file-upload-wrapper { margin-top: 2px !important; }
html[dir="rtl"] .maintenance-item-row .file-preview-container, html[dir="rtl"] .maintenance-item-row > .col-md-5 > .premium-form-group > .d-flex > .btn-premium-action { margin-right: 5px !important; margin-top: 2px !important; }
html[dir="ltr"] .maintenance-item-row .file-preview-container, html[dir="ltr"] .maintenance-item-row > .col-md-5 > .premium-form-group > .d-flex > .btn-premium-action { margin-left: 5px !important; margin-top: 2px !important; }
.maintenance-item-row .premium-file-box { height: 42px !important; min-height: 42px !important; padding: 0 10px !important; }
.maintenance-item-row .premium-file-box .file-icon-box { width: 24px !important; height: 24px !important; font-size: 0.9rem !important; }
.maintenance-item-row .btn-premium-action { width: 42px !important; height: 42px !important; margin: 0 !important; transform: none !important; display: inline-flex !important; align-items: center !important; justify-content: center !important; }
.maintenance-item-row .action-btn-wrapper { min-height: 42px !important; height: 42px !important; margin-top: 0 !important; display: flex !important; align-items: center !important; }
.maintenance-item-row .file-preview-container { height: 42px !important; display: flex !important; align-items: center !important; }
.maintenance-item-row .d-flex.align-items-center.w-100 { height: 42px !important; }
.maintenance-item-row .premium-form-group > label.premium-label { margin-bottom: 8px !important; height: 21px !important; display: block !important; }

/* --- Sticky Table Actions --- */
.sticky-actions {
    position: sticky !important;
    left: 0 !important;
    z-index: 2;
    background-color: #fff;
}
th.sticky-actions {
    z-index: 3;
}
.table-hover tbody tr:hover .sticky-actions {
    background-color: #f6f6f6;
}
.dark-layout .sticky-actions,
